import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Equipment from './Equipment';
import EquipmentSearch from './EquipmentSearch';
import styled from 'styled-components';

// Styled components for layout
const Container = styled.div`
  display: flex;
  max-width: 1200px;
  margin: 0 auto;
  padding: 20px;
`;

const Content = styled.div`
  flex: 3;
`;

const Sidebar = styled.div`
  flex: 1;
  padding: 15px;
  border-left: 1px solid #ddd;
  margin-left: 20px;
  max-height: 600px;
  overflow-y: auto;
  background-color: #f7f9fc;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
  border-radius: 8px;
`;

const Modal = styled.div`
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  background-color: white;
  padding: 20px;
  z-index: 1000;
  box-shadow: 0 5px 15px rgba(0, 0, 0, 0.3);
  border-radius: 10px;
  width: 80%;
  max-width: 500px;
`;

const Overlay = styled.div`
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.7);
  z-index: 999;
`;

const TabContainer = styled.div`
  display: flex;
  margin-top: 20px;
  button {
    flex: 1;
    padding: 10px;
    cursor: pointer;
    background: #f2f2f2;
    border: none;
    outline: none;
    &:hover {
      background: #ddd;
    }
    &.active {
      background: #ddd;
      font-weight: bold;
    }
  }
`;

const EquipmentPage = () => {
  const [equipmentData, setEquipmentData] = useState([]);
  const [selection, setSelection] = useState([]);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedItem, setSelectedItem] = useState(null);
  const [activeTab, setActiveTab] = useState('beginner');
  const itemsPerPage = 20;

  // Fetch equipment data from the API
  const fetchData = async (searchTerm = '', category = 'all', minPrice = '', maxPrice = '') => {
    setLoading(true);
    try {
      const response = await axios.get('/api/equipment', {
        params: { page: currentPage, search: searchTerm, category, min_price: minPrice, max_price: maxPrice },
      });
      setEquipmentData(response.data.equipment);
      setTotalPages(response.data.total_pages);
      setLoading(false);
    } catch (error) {
      setError('Failed to load data');
      setLoading(false);
    }
  };

  // Load initial data and selection
  useEffect(() => {
    fetchData();
  }, [currentPage]);

  // Add to selection
  const addToSelection = (item) => {
    setSelection((prevSelection) => [...prevSelection, item]);
  };

  // Remove from selection
  const removeFromSelection = (itemId) => {
    setSelection((prevSelection) => prevSelection.filter((item) => item.id !== itemId));
  };

  // Open and close modal
  const openModal = (item) => {
    setSelectedItem(item);
    setIsModalOpen(true);
  };
  const closeModal = () => {
    setIsModalOpen(false);
    setSelectedItem(null);
  };

  // Sidebar item click
  const handleSidebarItemClick = (item) => openModal(item);

  // Pagination controls
  const nextPage = () => {
    if (currentPage < totalPages) setCurrentPage((prev) => prev + 1);
  };

  const prevPage = () => {
    if (currentPage > 1) setCurrentPage((prev) => prev - 1);
  };

  if (loading) return <p>Loading...</p>;
  if (error) return <p>{error}</p>;

  // Render
  return (
    <Container>
      <Content>
        <EquipmentSearch onSearch={fetchData} />
        <Equipment equipment={equipmentData} onAddToSelection={addToSelection} />

        <div style={{ display: 'flex', justifyContent: 'center', marginTop: '10px' }}>
          <button onClick={prevPage} disabled={currentPage === 1}>Previous</button>
          <span style={{ margin: '0 10px' }}>Page {currentPage} of {totalPages}</span>
          <button onClick={nextPage} disabled={currentPage === totalPages}>Next</button>
        </div>

        {/* Tabbed Information Section */}
        <TabContainer>
          {['beginner', 'training', 'race day', 'expert'].map((tab) => (
            <button
              key={tab}
              className={activeTab === tab ? 'active' : ''}
              onClick={() => setActiveTab(tab)}
            >
              {tab.charAt(0).toUpperCase() + tab.slice(1)}
            </button>
          ))}
        </TabContainer>

        {/* Render content based on active tab */}
        {activeTab === 'beginner' && (
          <div>
            <h3>Beginner Tips</h3>
            <p>Starting out? Focus on budget-friendly gear to get comfortable with the basics.</p>
            <ul>
              <li>Entry-level road bike</li>
              <li>Basic helmet and gloves</li>
              <li>Swim goggles and beginner-friendly wetsuit</li>
            </ul>
          </div>
        )}
        {activeTab === 'training' && (
          <div>
            <h3>Training Tips</h3>
            <p>Mid-range, durable gear for consistent training.</p>
            <ul>
              <li>Comfortable running shoes for high mileage</li>
              <li>Mid-tier bike components for reliability</li>
              <li>Water-resistant GPS watch for tracking</li>
            </ul>
          </div>
        )}
        {activeTab === 'race day' && (
          <div>
            <h3>Race Day Gear</h3>
            <p>Gear for performance, including hydration packs and race shoes.</p>
            <ul>
              <li>Aerodynamic bike setup</li>
              <li>Lightweight running shoes</li>
              <li>Nutrition packs and hydration</li>
            </ul>
          </div>
        )}
        {activeTab === 'expert' && (
          <div>
            <h3>Expert Gear</h3>
            <p>Top-tier equipment for maximizing performance.</p>
            <ul>
              <li>High-end triathlon bike with carbon frame</li>
              <li>Advanced wetsuit for optimal buoyancy</li>
              <li>Custom-fitted running shoes</li>
            </ul>
          </div>
        )}
      </Content>

      {/* Sidebar */}
      <Sidebar>
        <h2>Your Selection</h2>
        {selection.length > 0 ? (
          <ul>
            {selection.map((item) => (
              <li key={item.id} onClick={() => handleSidebarItemClick(item)}>
                {item.name || 'Unnamed Item'} - ${item.price || '0.00'}
                <button onClick={(e) => { e.stopPropagation(); removeFromSelection(item.id); }}>Remove</button>
              </li>
            ))}
          </ul>
        ) : (
          <p>No items added yet.</p>
        )}
        <div>Total: ${selection.reduce((sum, item) => sum + (item.price || 0), 0).toFixed(2)}</div>
      </Sidebar>

      {/* Modal for item details */}
      {isModalOpen && (
        <>
          <Overlay onClick={closeModal} />
          <Modal>
            <h2>{selectedItem?.name}</h2>
            <p>Price: ${selectedItem?.price}</p>
            <p>{selectedItem?.description}</p>
            <button onClick={closeModal}>Close</button>
          </Modal>
        </>
      )}
    </Container>
  );
};

export default EquipmentPage;
